public class MainActivity extends Activity {
 private final Handler cloudUpdates=new Handler(Looper.getMainLooper());private final Runnable cloudTick=new Runnable(){public void run(){CloudSync.kick(MainActivity.this);cloudUpdates.postDelayed(this,30000);}};
 private WebView web;private boolean loaded=false,documentOpen=false,backupExport=false;
 private String requestedId="",pendingEmail="",documentMode="";private byte[] documentBytes;private char[] restorePassword;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final Handler updates=new Handler(Looper.getMainLooper());private final Runnable refreshTask=()->refresh();private final BroadcastReceiver changes=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if("in.paisa.DATA_CHANGED".equals(i.getAction())){updates.removeCallbacks(refreshTask);updates.postDelayed(refreshTask,250);}}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);IntentFilter changesFilter=new IntentFilter("in.paisa.DATA_CHANGED");if(Build.VERSION.SDK_INT>=33)registerReceiver(changes,changesFilter,Context.RECEIVER_NOT_EXPORTED);else registerLegacyChanges(changesFilter);getWindow().setStatusBarColor(Color.rgb(247,248,244));getWindow().setNavigationBarColor(Color.rgb(247,248,244));getWindow().getDecorView().setSystemUiVisibility(android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);web=new WebView(this);web.setBackgroundColor(Color.rgb(247,248,244));web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setBlockNetworkLoads(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new NativeBridge(this,worker),"PaisaAndroid");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onPageFinished(WebView v,String url){loaded=true;refresh();}});setContentView(web);readIntent(getIntent());web.loadUrl("file:///android_asset/index.html");Reminders.schedule(this);}
 // API 26–32 do not implement RECEIVER_NOT_EXPORTED; a signature permission protects this fallback.
 @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag")
 private void registerLegacyChanges(IntentFilter filter){registerReceiver(changes,filter,"in.paisa.personal.permission.INTERNAL",null);}
 private void readIntent(Intent intent){requestedId=intent.getStringExtra("entryId");String action=intent.getAction();if(Intent.ACTION_SEND.equals(action)){String text=intent.getStringExtra(Intent.EXTRA_TEXT);if(text!=null)pendingEmail=text.substring(0,Math.min(text.length(),200000));else if(intent.getParcelableExtra(Intent.EXTRA_STREAM)!=null){android.net.Uri uri=intent.getParcelableExtra(Intent.EXTRA_STREAM);if("content".equals(uri.getScheme()))worker.execute(()->{try{pendingEmail=new String(read(uri,200000),StandardCharsets.UTF_8);refresh();}catch(Exception e){tell("Could not read shared email text");}});}}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);readIntent(intent);refresh();}
 @Override protected void onResume(){super.onResume();refresh();CloudSync.kick(this);cloudUpdates.removeCallbacks(cloudTick);cloudUpdates.postDelayed(cloudTick,30000);if(!worker.isShutdown())worker.execute(()->Reminders.check(this));}
 @Override protected void onPause(){cloudUpdates.removeCallbacks(cloudTick);super.onPause();}
 @Override protected void onDestroy(){updates.removeCallbacks(refreshTask);unregisterReceiver(changes);worker.shutdown();if(restorePassword!=null)Arrays.fill(restorePassword,'\0');if(web!=null)web.destroy();super.onDestroy();}
 @Override public void onBackPressed(){web.evaluateJavascript("window.paisaBack && window.paisaBack()",v->{if(!"true".equals(v))super.onBackPressed();});}
 public void refresh(){if(!loaded)return;runOnUiThread(()->{web.evaluateJavascript("window.paisaRefresh && window.paisaRefresh()",null);if(requestedId!=null&&!requestedId.isEmpty()){String id=requestedId;requestedId="";web.evaluateJavascript("window.paisaOpen && window.paisaOpen("+JSONObject.quote(id)+")",null);}if(!pendingEmail.isEmpty()){String text=pendingEmail;pendingEmail="";web.evaluateJavascript("window.paisaImportText && window.paisaImportText("+JSONObject.quote(text)+")",null);}});}
 public void tell(String message){runOnUiThread(()->{if(loaded)web.evaluateJavascript("window.paisaNotice && window.paisaNotice("+JSONObject.quote(message==null?"Please try again":message)+")",null);});}
 public void requestSms(){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Automatic SMS tracking").setMessage("SMS permission provides inbox access. Supported financial messages are processed on this phone; OTPs and personal messages are not uploaded or retained. Permission is optional. You can still add entries manually.").setPositiveButton("Allow SMS",(d,w)->{ArrayList<String> list=new ArrayList<>();for(String p:new String[]{Manifest.permission.RECEIVE_SMS,Manifest.permission.READ_SMS})if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)list.add(p);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)list.add(Manifest.permission.POST_NOTIFICATIONS);if(!list.isEmpty())requestPermissions(list.toArray(new String[0]),10);else tell("SMS tracking permission enabled");}).setNegativeButton("Later",null).show());}
 public void requestNotificationPermission(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);else tell("Notification permission enabled");});}
 public void requestNotificationAccess(){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Bank & Gmail payment alerts").setMessage("Android notification access is broad. Paisa filters only the apps you selected, processes supported financial alerts locally, and ignores other notifications. Gmail tracking uses visible payment-email alerts; it does not log in to or sync your mailbox. Truncated alerts can be missed.").setPositiveButton("Open Android settings",(d,w)->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS))).setNegativeButton("Later",null).show());}
 public void exportDocument(byte[] bytes,String mime,String name,boolean isBackup){runOnUiThread(()->{if(documentOpen){tell("Finish the current file picker first");return;}documentOpen=true;documentMode="export";documentBytes=bytes;backupExport=isBackup;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name),20);}catch(Exception e){documentOpen=false;documentBytes=null;tell("No file picker available");}});}
 public void pickDocument(String mode,char[] password){runOnUiThread(()->{if(documentOpen){if(password!=null)Arrays.fill(password,'\0');tell("Finish the current file picker first");return;}documentOpen=true;documentMode=mode;restorePassword=password;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),21);}catch(Exception e){documentOpen=false;if(password!=null)Arrays.fill(password,'\0');tell("No file picker available");}});}
 private byte[] read(android.net.Uri uri,int max)throws Exception{try(InputStream input=getContentResolver().openInputStream(uri);ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=input.read(bytes))!=-1){if(output.size()+n>max)throw new IllegalArgumentException("File is too large");output.write(bytes,0,n);}return output.toByteArray();}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=20&&request!=21)return;documentOpen=false;String mode=documentMode;char[] password=restorePassword;restorePassword=null;byte[] bytes=documentBytes;documentBytes=null;boolean wasBackup=backupExport;backupExport=false;if(result!=RESULT_OK||data==null||data.getData()==null){if(password!=null)Arrays.fill(password,'\0');return;}android.net.Uri uri=data.getData();
  worker.execute(()->{try{
   if(mode.equals("export")){if(bytes==null)throw new IllegalArgumentException("Export interrupted; try again");try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}if(wasBackup)try(Store store=new Store(this)){JSONObject cfg=store.settings().put("lastBackupAt",System.currentTimeMillis());store.setSettings(cfg);}tell(wasBackup?"Encrypted backup saved. Keep the password safe.":"CSV saved");refresh();}
   else if(mode.equals("email")){pendingEmail=EmailText.decode(new String(read(uri,200000),StandardCharsets.UTF_8));refresh();}
   else if(mode.equals("restore")){byte[] encrypted=read(uri,32*1024*1024);JSONObject restored=new JSONObject(new String(BackupCipher.decrypt(encrypted,password),StandardCharsets.UTF_8));Ledger.validate(restored);if(restored.optInt("version")!=3)throw new IllegalArgumentException("Unsupported backup version");char[] secret=password.clone();runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Restore this backup?").setMessage("Google sync will stop. This will replace the current accounts, transactions, notes, rules, bills, budgets and subscriptions with "+restored.optJSONArray("entries").length()+" backed-up records. A password-encrypted safety copy of the current data will be kept on this phone.").setPositiveButton("Restore",(d,w)->worker.execute(()->{try{CloudSync.beforeManualRestore(this);restored.getJSONObject("settings").put("syncPreference","local");}catch(Exception e){tell("Restore stopped: "+e.getMessage());Arrays.fill(secret,'\0');return;}try(Store store=new Store(this)){boolean done=false;for(int attempt=0;attempt<3;attempt++){JSONObject before=store.backup();byte[] safety=BackupCipher.encrypt(before.toString().getBytes(StandardCharsets.UTF_8),secret);android.util.AtomicFile file=new android.util.AtomicFile(new File(getFilesDir(),"pre-restore.paisabackup"));FileOutputStream out=file.startWrite();try{out.write(safety);file.finishWrite(out);}catch(Exception failure){file.failWrite(out);throw failure;}try{store.restoreIfUnchanged(before,restored);done=true;break;}catch(java.util.ConcurrentModificationException changed){tell("New payment arrived; refreshing the safety copy…");}}if(!done)throw new IllegalArgumentException("Payments kept arriving during restore. Current data is safe; retry when idle.");Reminders.schedule(this);tell("Backup restored. Previous data kept in a local safety copy.");refresh();}catch(Exception e){tell("Restore failed: "+e.getMessage());}finally{Arrays.fill(secret,'\0');}})).setNegativeButton("Cancel",(d,w)->Arrays.fill(secret,'\0')).setOnCancelListener(d->Arrays.fill(secret,'\0')).show());}
  }catch(Exception e){tell(e.getMessage());}finally{if(password!=null)Arrays.fill(password,'\0');}});
 }
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);Reminders.schedule(this);refresh();tell("Permissions updated. Check Tracking for current status.");}
}
